BEGIN;
DO $$ DECLARE a uuid;s uuid;bad uuid;bs uuid;m uuid;m2 uuid;e uuid;e2 uuid;ref uuid;cred uuid;review uuid;checkin uuid;r jsonb;info jsonb;sid uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('event-super@example.test','fictional','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('event-ordinary@example.test','fictional','admin',true) RETURNING id INTO bad;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('a1',32)) RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(bad,repeat('a2',32)) RETURNING id INTO bs;
 INSERT INTO public.members(name,email) VALUES('Fictional Event Member','event-linked@gatech.edu') RETURNING id INTO m;
 INSERT INTO public.members(name,email) VALUES('Other Event Member','event-other@gatech.edu') RETURNING id INTO m2;
 BEGIN PERFORM public.reward_event_admin(bad,bs,'list','{}');RAISE EXCEPTION 'Ordinary admin read event connections';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.reward_event_admin(a,s,'save',jsonb_build_object('title','Fictional DevFest','origin','https://devfest.example.org/','opensAt',now()-interval '1 hour','closesAt',now()+interval '1 hour','active',true,'activityId',NULL,'keyHash',repeat('b1',32),'encryptedKey','fictional-key'),repeat('b2',32),repeat('b3',32));e:=(r->>'id')::uuid;
 IF r->>'encryptedKey'<>'fictional-key' THEN RAISE EXCEPTION 'Create credential receipt unavailable';END IF;
 IF public.reward_event_admin(a,s,'save','{}',repeat('b2',32),repeat('b3',32))<>r THEN RAISE EXCEPTION 'Create retry did not reuse receipt';END IF;
 r:=public.reward_event_admin(a,s,'list','{}');IF r::text LIKE '%fictional-key%' OR r::text LIKE '%key_hash%' THEN RAISE EXCEPTION 'Inventory leaked key';END IF;
 r:=public.reward_event_admin(a,s,'save',jsonb_build_object('title','Other Event','origin','https://other.example.org/','opensAt',now()-interval '1 hour','closesAt',now()+interval '1 hour','active',true,'activityId',NULL,'keyHash',repeat('f1',32),'encryptedKey','other-key'),repeat('f2',32),repeat('f3',32));e2:=(r->>'id')::uuid;
 BEGIN PERFORM public.reward_event_external(e,repeat('ff',32),'membership','{}');RAISE EXCEPTION 'Bad key worked';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 sid:=public.reward_open_session('event-linked@gatech.edu','custom:gatech:event-linked',repeat('c1',32),repeat('c2',32));
 r:=public.reward_event_member(repeat('c1',32),repeat('c2',32),'code',jsonb_build_object('eventId',e,'tokenHash',repeat('c3',32),'encryptedCode','fictional-code'));
 BEGIN PERFORM public.reward_event_member(repeat('c1',32),repeat('ff',32),'code',jsonb_build_object('eventId',e));RAISE EXCEPTION 'Bad member CSRF worked';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.reward_event_external(e,repeat('b1',32),'redeem',jsonb_build_object('codeHash',repeat('c3',32),'accountHash',repeat('c4',32)));ref:=(r->>'memberRef')::uuid;
 BEGIN PERFORM public.reward_event_external(e2,repeat('f1',32),'membership',jsonb_build_object('memberRef',ref));RAISE EXCEPTION 'Event key crossed another event';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.reward_event_external(e2,repeat('f1',32),'redeem',jsonb_build_object('codeHash',repeat('c3',32),'accountHash',repeat('c4',32)));RAISE EXCEPTION 'Event key redeemed another event code';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 IF r::text LIKE '%event-linked@gatech.edu%' OR r::text LIKE '%'||m::text||'%' OR r->>'active'<>'true' THEN RAISE EXCEPTION 'Event reference leaked global identity';END IF;
 IF public.reward_event_external(e,repeat('b1',32),'redeem',jsonb_build_object('codeHash',repeat('c3',32),'accountHash',repeat('c4',32)))<>r THEN RAISE EXCEPTION 'Lost link response could not retry';END IF;
 BEGIN PERFORM public.reward_event_external(e,repeat('b1',32),'redeem',jsonb_build_object('codeHash',repeat('c3',32),'accountHash',repeat('ff',32)));RAISE EXCEPTION 'Link replay changed account';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 BEGIN PERFORM public.reward_event_external(e,repeat('b1',32),'points',jsonb_build_object('memberRef',ref));RAISE EXCEPTION 'Event credential awarded points';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'VALIDATION_ERROR' THEN RAISE;END IF;END;
 INSERT INTO public.reward_credentials(member_id,kind,label,token_hash,encrypted_token) VALUES(m,'card','Fictional card',repeat('d1',32),'fictional') RETURNING id INTO cred;
 info:=public.reward_event_admin(a,s,'lookup',jsonb_build_object('eventId',e,'credentialHash',repeat('d1',32)));
 IF info->>'memberRef'<>ref::text THEN RAISE EXCEPTION 'Card did not link to event account';END IF;
 r:=public.reward_event_admin(a,s,'review',jsonb_build_object('eventId',e,'eventRevision',1,'credentialHash',repeat('d1',32),'memberRef',ref),repeat('d2',32),repeat('d3',32));review:=(r->>'reviewId')::uuid;
 r:=public.reward_event_admin(a,s,'begin',jsonb_build_object('reviewId',review),repeat('d4',32),repeat('d5',32));checkin:=(r->>'id')::uuid;
 IF r->>'state'<>'pending' THEN RAISE EXCEPTION 'Attendance confirmed before external backend';END IF;
 IF public.reward_event_admin(a,s,'begin',jsonb_build_object('reviewId',review),repeat('e4',32),repeat('e5',32))->>'id'<>checkin::text THEN RAISE EXCEPTION 'Second tap created duplicate pending checkin';END IF;
 UPDATE public.reward_event_reviews SET expires_at=now()-interval '1 minute' WHERE id=review;
 IF public.reward_event_admin(a,s,'begin',jsonb_build_object('reviewId',review),repeat('e6',32),repeat('e7',32))->>'recoveryOnly'<>'true' THEN RAISE EXCEPTION 'Expired review allowed a fresh remote write';END IF;
 r:=public.reward_event_admin(a,s,'finish',jsonb_build_object('reviewId',review,'externalId','fictional-event-receipt'),repeat('d4',32),repeat('d5',32));
 IF r->>'state'<>'completed' OR(SELECT count(*) FROM public.reward_event_checkins WHERE event_id=e)<>1 THEN RAISE EXCEPTION 'Checkin did not complete once';END IF;
 IF public.reward_event_admin(a,s,'begin',jsonb_build_object('reviewId',review),repeat('e4',32),repeat('e5',32))->>'state'<>'completed' THEN RAISE EXCEPTION 'Lost attendance response cannot recover';END IF;
 IF EXISTS(SELECT 1 FROM public.reward_ledger WHERE member_id=m) THEN RAISE EXCEPTION 'Checkin automatically awarded points';END IF;
 r:=public.reward_event_admin(a,s,'rotate',jsonb_build_object('id',e,'revision',1,'keyHash',repeat('e1',32),'encryptedKey','rotated-key'),repeat('e2',32),repeat('e3',32));
 BEGIN PERFORM public.reward_event_external(e,repeat('b1',32),'membership',jsonb_build_object('memberRef',ref));RAISE EXCEPTION 'Old key survived rotation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF public.reward_event_external(e,repeat('e1',32),'membership',jsonb_build_object('memberRef',ref))->>'active'<>'true' THEN RAISE EXCEPTION 'New key did not work';END IF;
 UPDATE public.members SET email='event-changed@gatech.edu' WHERE id=m;
 IF EXISTS(SELECT 1 FROM public.reward_event_links WHERE id=ref AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Directory email change kept event binding';END IF;
 BEGIN PERFORM public.reward_event_external(e,repeat('e1',32),'membership',jsonb_build_object('memberRef',ref));RAISE EXCEPTION 'Revoked link survived';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF has_table_privilege('anon','public.reward_event_connections','SELECT') OR has_table_privilege('authenticated','public.reward_event_codes','SELECT') OR has_function_privilege('anon','public.reward_event_external(uuid,text,text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'New event tables/functions exposed';END IF;
END $$;
ROLLBACK;
